dtype = torch.float16, varlen = False, dropout_p = 0.5
@pytest.mark.flash_attention_backward @pytest.mark.skipif(flag_gems.vendor_name != "nvidia", reason="direct generic NVIDIA core regression") @pytest.mark.parametrize("dtype", [torch.float16, torch.bfloat16]) @pytest.mark.parametrize("varlen", [False, True]) @pytest.mark.parametrize("dropout_p", [0.0, 0.5]) def test_dropout_derivative_identical_keys(dtype, varlen, dropout_p): m, n, heads, width, seed = 128, 256, 2, 32, 7331 q = torch.zeros((1, m, heads, width), dtype=dtype, device=flag_gems.device) k = torch.full((1, n, heads, width), 0.125, dtype=dtype, device=flag_gems.device) v = torch.ones_like(k) grad = torch.full_like(q, 1 / q.numel()) keep = torch.ones((1, heads, m, n), dtype=torch.bool, device=flag_gems.device) if dropout_p: _backward_mask[(triton.cdiv(keep.numel(), 256),)](keep, seed, m, n, heads, varlen, 256) weights = keep.double() / (n * (1 - dropout_p)) out = weights.sum(-1).permute(0, 2, 1).unsqueeze(-1).expand_as(q).to(dtype).contiguous() lse = torch.full((1, heads, m), math.log(n), dtype=torch.float32, device=flag_gems.device) expected_dv = weights.sum(-2).permute(0, 2, 1).unsqueeze(-1).expand_as(v) / q.numel() options = dict(max_seqlen_q=m, max_seqlen_k=n, is_dropout=bool(dropout_p), dropout_p=dropout_p, rng_state=(seed, 0), softmax_scale=width ** -0.5) args = (grad, q, k, v, out, lse) if varlen: args = tuple(t.squeeze(0) for t in args[:5]) + (lse.squeeze(0).T.contiguous(),) options.update(cu_seq_q=torch.tensor([0, m], dtype=torch.int32, device=flag_gems.device), cu_seq_k=torch.tensor([0, n], dtype=torch.int32, device=flag_gems.device)) dq, dk, dv, _ = flash_attn_backward(*args, **options) if varlen: dv = dv.unsqueeze(0) # Identical keys make Q irrelevant for a fixed mask; Q=0 also makes dK zero. > torch.testing.assert_close(dq, torch.zeros_like(dq), rtol=0, atol=1e-6) E AssertionError: Tensor-likes are not close! E E Mismatched elements: 8192 / 8192 (100.0%) E Greatest absolute difference: 8.678436279296875e-05 at index (0, 9, 0, 0) (up to 1e-06 allowed) E Greatest relative difference: inf at index (0, 0, 0, 0) (up to 0 allowed)
